const now = new Date();
const fmt = (d) => `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;

const hoje = fmt(now);
const dtFim7 = new Date(now);
dtFim7.setDate(dtFim7.getDate() + 7);
const fimSemana = fmt(dtFim7);

// Retorna 3 itens — um por endpoint
return [
  { json: { url: 'agendamentos',            dtInicio: hoje,      dtFim: fimSemana, tipo: 'abertos'     } },
  { json: { url: 'agendamentos/finalizados', dtInicio: hoje,      dtFim: hoje,      tipo: 'finalizados'  } },
  { json: { url: 'agendamentos/cancelados',  dtInicio: hoje,      dtFim: hoje,      tipo: 'cancelados'   } }
];

const agendamentos = [];

const normalizar = (a) => {
  const dtParts = (a.dtAgenda || '').split('/');
  const dataISO = dtParts.length === 3 ? `${dtParts[2]}-${dtParts[1]}-${dtParts[0]}` : null;
  const dataHora = dataISO && a.hrConsulta ? new Date(`${dataISO}T${a.hrConsulta}:00`) : null;
  return {
    json: {
      belle_id:          a.codConsulta,
      belle_cliente_cod: a.cliente?.cod || '',
      nome_cliente:      (a.cliente?.nome || '').replace(/'/g, "''"),
      celular_cliente:   a.cliente?.celular || '',
      cod_profissional:  a.prof?.cod || '',
      nome_profissional: (a.prof?.nome || '').replace(/'/g, "''"),
      nome_sala:         a.sala?.nome || '',
      servicos:          JSON.stringify(a.servicos || []),
      dt_agenda:         dataISO,
      hr_consulta:       a.hrConsulta || '',
      data_hora:         dataHora ? dataHora.toISOString() : null,
      status:            a.status || '',
      tipo:              a.tipo || '',
      observacao:        (a.observacao || '').replace(/'/g, "''")
    }
  };
};

for (const item of $input.all()) {
  const data = item.json;
  if (Array.isArray(data)) {
    for (const a of data) {
      if (a.codConsulta) agendamentos.push(normalizar(a));
    }
  } else if (data && data.codConsulta) {
    agendamentos.push(normalizar(data));
  }
}

console.log(`Total de agendamentos: ${agendamentos.length}`);
return agendamentos;
